CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE users (id uuid PRIMARY KEY, email text NOT NULL UNIQUE, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE purchases (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, merchant text NOT NULL CHECK(length(merchant) BETWEEN 1 AND 160), item text NOT NULL CHECK(length(item) BETWEEN 1 AND 300), amount bigint NOT NULL CHECK(amount > 0 AND amount <= 9007199254740991), currency text NOT NULL, deadline date NOT NULL, notes text NOT NULL DEFAULT '', version integer NOT NULL DEFAULT 1, archived boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX purchases_owner_created ON purchases(user_id, created_at DESC);
CREATE TABLE returns (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, purchase_id uuid NOT NULL UNIQUE REFERENCES purchases ON DELETE CASCADE, state text NOT NULL DEFAULT 'requested' CHECK(state IN ('requested','packed','dropped_off','delivered','resolved','cancelled')), expected bigint NOT NULL CHECK(expected > 0), fees bigint NOT NULL DEFAULT 0 CHECK(fees >= 0), label text NOT NULL DEFAULT '', carrier text NOT NULL DEFAULT '', category integer NOT NULL DEFAULT 3 CHECK(category BETWEEN 0 AND 3), method integer NOT NULL DEFAULT 2 CHECK(method BETWEEN 0 AND 2), features vector(8), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX returns_owner ON returns(user_id);
CREATE TABLE refunds (id uuid PRIMARY KEY, return_id uuid NOT NULL REFERENCES returns ON DELETE CASCADE, amount bigint NOT NULL CHECK(amount > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE runs (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, name text NOT NULL CHECK(length(name) BETWEEN 1 AND 160), planned_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE run_assignments (run_id uuid NOT NULL REFERENCES runs ON DELETE CASCADE, return_id uuid NOT NULL UNIQUE REFERENCES returns ON DELETE CASCADE, stop_name text NOT NULL, position integer NOT NULL CHECK(position >= 0), PRIMARY KEY(run_id, return_id));
CREATE TABLE activity (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE, aggregate_id uuid NOT NULL, kind text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox (id uuid PRIMARY KEY, aggregate_id uuid NOT NULL, kind text NOT NULL, schema_version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz, attempts integer NOT NULL DEFAULT 0, next_attempt_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX outbox_pending ON outbox(next_attempt_at) WHERE published_at IS NULL;
